// Üretilen dosya: tool/ozgun/uret.py. Araştırma Yöntemleri · Araştırma soruları ve hipotez kurma uygulamaları (kolay).
const ozResearch6Kolay = <(String, String, List<String>, String)>[
  ('Bir araştırma önerisinde "Gençlerin kitap okuma alışkanlığı" ifadesi hangi öğeye karşılık gelir?', 'Araştırma konusu', ['Araştırma sorusu', 'Araştırma hipotezi', 'Bağımlı değişken'], 'Bu ifade incelenecek genel alanı adlandırır; soru biçiminde değildir ve bir ilişki ya da beklenti öne sürmez. Bu yüzden konudur.'),
  ('Araştırma sürecinde problem durumu, araştırma sorusu ve hipotez genellikle hangi sırayla belirginleşir?', 'Problem durumu, araştırma sorusu, hipotez', ['Hipotez, problem durumu, araştırma sorusu', 'Araştırma sorusu, hipotez, problem durumu', 'Hipotez, araştırma sorusu, problem durumu'], 'Önce bir sorun fark edilir, sonra bu sorun yanıtlanabilir bir soruya dönüştürülür, en son sorunun olası yanıtı hipotez olarak yazılır.'),
  ('Bir öğrenci önerisinin başlığına "Plastik kirliliği" yazmış ve hemen veri toplamaya başlamak istiyor. Öğretmenin uyarısı hangisi olmalıdır?', 'Önce konuyu yanıtlanabilir bir soruya dönüştürmelisin', ['Önce kaynakçayı istenen stile göre eksiksiz biçimlendirmelisin', 'Önce sonuç bölümünü yazmalısın', 'Önce örneklemi iki katına çıkarmalısın'], 'Genel bir konu hangi verinin toplanacağını belirlemez. Veri toplamadan önce neyin, kimde, nasıl inceleneceğini gösteren bir araştırma sorusu gerekir.'),
  ('Bir araştırma raporunda "Bu çalışmanın amacı, okul bahçesindeki ağaç türlerinin sayısını belirlemektir." cümlesi yer alıyor. Bu amaç cümlesine en uygun araştırma sorusu hangisidir?', 'Okul bahçesinde kaç farklı ağaç türü vardır?', ['Ağaçlar okulu daha güzel yapar mı?', 'Ağaç dikmek neden önemlidir?', 'Okul bahçesine bu yıl daha çok ağaç dikilmesi gerekir mi?'], 'Amaç cümlesi bir sayım hedefliyor; ona karşılık gelen soru da tür sayısını sormalıdır. Öteki seçenekler ya değer yargısı ya da başka bir amaç içerir.'),
  ('Aşağıdaki araştırma sorularından hangisi en dar kapsamlıdır?', 'Rize\'de 2020-2023 arasında yetiştirilen çayın hasat dönemlerine göre verimi nasıl değişti?', ['Türkiye\'de tarım nasıl değişti?', 'Karadeniz Bölgesi\'nde çay tarımı geçmişten bugüne nasıl değişti?', 'Türkiye\'de çay üretimi yıllara göre nasıl değişti?'], 'Bu soru yeri (Rize), zamanı (2020-2023) ve değişkeni (hasat dönemine göre verim) birlikte sınırlar. Ötekiler bu boyutlardan en az birini açık bırakır.'),
  ('Konu daraltmada sık önerilen "huni" yaklaşımı ne anlatır?', 'Genel alandan başlayıp adım adım tek bir soruya inmeyi', ['Önce sonucu yazıp sonra konuyu seçmeyi', 'Birçok konuyu aynı anda araştırıp en iyisini seçmeyi', 'Yalnızca dar bir kaynaktan başlayıp genişlemeyi'], 'Huni benzetmesi, geniş bir ilgi alanından başlayıp her adımda bir boyutu sınırlayarak yanıtlanabilir tek bir soruya varmayı anlatır.'),
  ('Bir öğrenci "Deprem" konusunu daraltırken "1999 Marmara Depremi\'nden sonra çıkarılan yapı denetimi düzenlemeleri" noktasına geliyor. Bu daraltma için hangi yorum doğrudur?', 'Konu bir olay ve dönemle sınırlanarak incelenebilir hâle gelmiştir', ['Konu daha da genişlemiştir', 'Konu daraltma sırasında bir değer yargısına dönüşmüş ve araştırılamaz olmuştur', 'Konu artık hipotez gerektirmeyen bir başlık olmaktan çıkmıştır'], 'Belirli bir olay ve onu izleyen düzenlemelerle sınırlanan konu, kaynak taramasıyla incelenebilecek bir genişliğe inmiştir.'),
  ('"Lise öğrencilerinin günlük ortalama uyku süresi kaç saattir?" sorusu hangi tür araştırma sorusudur?', 'Betimsel', ['İlişkisel', 'Nedensel', 'Karşılaştırmalı'], 'Soru yalnız bir değişkenin bir gruptaki durumunu ortaya koymayı amaçlar; ilişki, fark ya da neden aramaz.'),
  ('"Öğrencilerin haftalık spor saati ile dikkat testi puanları arasında bir ilişki var mıdır?" sorusu hangi türdendir?', 'İlişkisel', ['Betimsel', 'Nedensel', 'Keşfedici nitel'], 'Soru iki değişkenin birlikte değişip değişmediğini sorar; birinin ötekine yol açtığını iddia etmez.'),
  ('Betimsel bir araştırma sorusu ile ilişkisel bir araştırma sorusu arasındaki temel fark nedir?', 'Betimsel soru bir durumu, ilişkisel soru değişkenlerin birlikte değişimini sorar', ['Betimsel soru hiçbir zaman sayısal veri kullanamaz, ilişkisel soru ise yalnızca sayısal veri kullanır', 'Betimsel soru hipotez ister, ilişkisel soru istemez', 'Betimsel soru nedensel sonuç verir, ilişkisel soru vermez'], 'Betimsel soru "ne kadar, nasıl dağılmış" gibi durum belirlemeye yöneliktir; ilişkisel soru en az iki değişken arasındaki bağı sorar.'),
  ('Aşağıdaki soru köklerinden hangisi bir sürecin işleyişini anlamaya yönelik bir araştırma sorusuna en uygun başlangıçtır?', '"Nasıl"', ['"Kaç tane"', '"Var mı"', '"Hangi yıl"'], '"Nasıl" ile başlayan sorular bir sürecin ya da deneyimin işleyişini açıklamaya yöneltir; ötekiler sayı, varlık ya da tarih gibi tek bir bilgi ister.'),
  ('Bir araştırmanın ana problemi "Okul bahçesindeki yeşil alanlar öğrencilerin teneffüs etkinliklerini nasıl etkilemektedir?" biçimindedir. Hangisi bu ana probleme uygun bir alt problemdir?', 'Yeşil alanda ve beton alanda oynanan oyun türleri farklılaşmakta mıdır?', ['Okulun kuruluş yılı nedir?', 'Okuldaki öğrencilerin en sevdiği ders hangisidir ve neden sevilir?', 'Kantinde en çok hangi ürün satılmaktadır?'], 'Alt problem, ana problemi daha küçük ve yanıtlanabilir parçalara ayırır. Yalnız doğru seçenek yeşil alan ile teneffüs etkinliği ilişkisinin bir parçasını sorar.'),
  ('Alt problemlerin ana problemle ilişkisi için hangisi doğrudur?', 'Yanıtları bir araya gelince ana problemi yanıtlamaya katkı sağlar', ['Her biri ana problemden bağımsız, kendi başına yeni bir araştırma konusudur', 'Ana problemden daha geniş kapsamlıdır', 'Araştırma bittikten sonra yazılır'], 'Alt problemler ana problemin bileşenleridir; birlikte yanıtlandıklarında ana probleme kapsamlı bir yanıt oluşturur.'),
  ('Ana problem ile alt problem arasındaki ilişkiyi en iyi anlatan benzetme hangisidir?', 'Bir yapbozun bütün resmi ile parçaları', ['Bir kitabın renkli kapağı ile en sondaki kaynakçası', 'Bir yarışmanın birincisi ile sonuncusu', 'Bir ağacın gölgesi ile meyvesi'], 'Alt problemler yapbozun parçaları gibidir; yerlerine oturduklarında ana problemin bütün resmini oluştururlar.'),
  ('Bir araştırma sorusunu değerlendirmek için kullanılan FINER kısaltmasındaki "F" (feasible) harfi hangi ölçütü anlatır?', 'Yapılabilirlik', ['Yenilik', 'Etiklik', 'İlgi çekicilik'], 'FINER: Feasible (yapılabilir), Interesting (ilgi çekici), Novel (yeni), Ethical (etik), Relevant (ilgili/önemli) sözcüklerinden oluşur.'),
  ('Bir lise öğrencisi "Uzay istasyonunda yetişen buğdayın verimi Dünya\'dakinden farklı mı?" sorusunu dönem projesi olarak seçmek istiyor. Bu soru FINER ölçütlerinden en açık biçimde hangisini karşılamaz?', 'Yapılabilirlik', ['İlgi çekicilik', 'Yenilik', 'Önem'], 'Soru ilginç ve önemli olabilir, ancak bir öğrencinin bu veriyi toplaması olanaksızdır; bu nedenle yapılabilirlik ölçütünü karşılamaz.'),
  ('"Öğrencilerin bir hafta boyunca hiç uyumamasının belleğe etkisi nedir?" sorusu FINER ölçütlerinden hangisine en açık biçimde aykırıdır?', 'Etik', ['Yenilik', 'İlgi çekicilik', 'İlgililik ve toplumsal önem'], 'Katılımcıları ağır uykusuzluğa maruz bırakmak sağlıklarına zarar verir; böyle bir soru bu biçimde araştırılamaz.'),
  ('FINER ölçütlerinin araştırmanın hangi aşamasında kullanılması en yararlıdır?', 'Soru seçilirken, veri toplamadan önce', ['Rapor basıldıktan sonra', 'Yalnızca dergi editörünün hakem değerlendirmesinde', 'Veri çözümlemesinin sonunda'], 'Bu ölçütler soru seçilirken uygulanırsa yapılamaz, etik dışı ya da gereksiz bir çalışmaya emek harcanması önlenir.'),
  ('FINER ölçütlerinde "I" (interesting) harfi için en doğru yorum hangisidir?', 'Soru araştırmacıyı ve okurları güdüleyecek kadar merak uyandırmalıdır', ['Soru mutlaka eğlenceli bir konuda olmalıdır', 'Soru en az iki değişken içermelidir', 'Soru yalnız alanın uzmanlarına ilginç gelmeli, başkalarını ilgilendirmemelidir'], 'İlgi çekicilik, araştırmacının süreç boyunca güdülenmesini ve sonuçların okurlarca önemsenmesini destekleyen ölçüttür.'),
  ('Sağlık araştırmalarında soru kurmak için kullanılan PICO çerçevesinde "P" harfi neyi gösterir?', 'Hasta ya da incelenen grup', ['Plasebo uygulamasının biçimi', 'Yayın türü', 'Ölçüm aracının puanı'], 'PICO: Population/Patient (grup), Intervention (müdahale), Comparison (karşılaştırma), Outcome (sonuç).'),
  ('"Tip 2 diyabetli yetişkinlerde günlük 30 dakikalık yürüyüş, yürüyüş yapmamaya kıyasla HbA1c değerini düşürür mü?" sorusunda PICO\'nun "C" öğesi hangisidir?', 'Yürüyüş yapmamak', ['Tip 2 diyabetli yetişkinler', 'Günlük 30 dakikalık yürüyüş', 'HbA1c değeri'], 'C (Comparison) müdahalenin karşılaştırıldığı koşuldur; burada yürüyüş yapmamaktır.'),
  ('"Okul öncesi çocuklarda flor vernik uygulaması diş çürüğü sayısını azaltır mı?" sorusunda PICO\'nun "O" öğesi hangisidir?', 'Çürük diş sayısındaki değişim', ['Okul öncesi dönemdeki çocuklar', 'Flor vernik uygulaması', 'Uygulama yapılmaması'], 'O (Outcome) ölçülen sonuçtur; burada çürük diş sayısındaki değişimdir.'),
  ('"Ergenlerde düzenli kahvaltı, kahvaltı atlamaya göre okul başarısını artırır mı?" sorusu için PICO öğeleri doğru eşleştirilmiştir. Hangisi müdahaledir (I)?', 'Her sabah kahvaltı yapılması', ['Ergenler', 'Kahvaltının atlandığı sabahlar', 'Okul başarısı'], 'I (Intervention) araştırmacının etkisini merak ettiği uygulamadır; burada düzenli kahvaltıdır.'),
  ('"Hangi müzik türü daha güzeldir?" sorusunu araştırılabilir hâle getiren düzenleme hangisidir?', 'Lise öğrencilerinin en çok dinlediklerini belirttikleri müzik türü hangisidir?', ['Klasik müzik bütün türler arasında neden en güzel olanıdır?', 'Güzel müzik nasıl olmalıdır?', 'Herkes hangi müzik türünü sevmelidir?'], '"Güzel" kişisel bir değerlendirmedir; ancak insanların tercihleri ölçülebilir. Doğru seçenek değer yargısını betimlenebilir bir tercihe çevirir.'),
  ('Aşağıdakilerden hangisi değer yargısı içermeyen, araştırılabilir bir sorudur?', 'Okul servisine binen öğrencilerin derse geç kalma sıklığı yürüyerek gelenlerden farklı mı?', ['Okul servisleri bütün öğrenciler için zorunlu olmalı mı?', 'Yürüyerek okula gitmek daha doğru değil mi?', 'Geç kalan öğrenciler cezalandırılmalı mı?'], 'Doğru seçenek gözlenebilir bir sıklığın iki grupta karşılaştırılmasını ister. Ötekiler ne yapılması gerektiğine ilişkin yargı içerir.'),
  ('"İyi", "kötü", "doğru", "daha uygun" gibi sözcükler bir araştırma sorusunda neden dikkatle kullanılmalıdır?', 'Ölçüt belirtilmezse yanıt kişiden kişiye değişir', ['Bu sözcükler Türkçede yanlış yazılır', 'Bu sözcükler soruyu çok kısaltır', 'Bu sözcükler kullanıldığında istatistiksel testler hesaplanamaz'], 'Bu sözcükler bir ölçüte bağlanmazsa öznel kalır. "Daha iyi" yerine "daha yüksek puan", "daha az hata" gibi gözlenebilir ifadeler kullanılmalıdır.'),
  ('Bir lise öğrencisi bir aylık sürede tamamlayacağı projesi için "Türkiye\'deki tüm lise öğrencilerinin okul doyumu" sorusunu seçmiş. Hangi değişiklik yapılabilirliği en çok artırır?', 'Kapsamı kendi okulundaki öğrencilerle sınırlamak', ['Soruya ikinci bir değişken ekleyip hipotez sayısını artırmak', 'Örneklemi tüm Avrupa\'ya genişletmek', 'Soruyu yönlü hipoteze çevirmek'], 'Bir ayda ulusal düzeyde veri toplamak bir öğrenci için gerçekçi değildir. Erişilebilir bir grupla sınırlamak soruyu yapılabilir kılar.'),
  ('Bir araştırma sorusunun yapılabilirliğini değerlendirirken aşağıdakilerden hangisi sorulmaz?', 'Soru başlıkta kaç sözcük tutar?', ['Gerekli katılımcılara ulaşabilir miyim?', 'Değişkenleri ölçecek aracım var mı?', 'Bu süre içinde veriyi toplayabilir miyim?'], 'Yapılabilirlik zaman, erişim, araç-gereç ve bütçe gibi koşullarla ilgilidir; başlığın uzunluğu bunlardan biri değildir.'),
  ('Bir öğrenci kuş göçünün zamanlamasıyla ilgili bir soru seçmiş, ancak projesini teslim edeceği tarih göç mevsiminden önce. Bu durum hangi tür yapılabilirlik sorunudur?', 'Zamanlama sorunu', ['Bütçe sorunu', 'Etik sorun', 'Ölçme aracı sorunu'], 'Veri, ancak belirli bir dönemde toplanabiliyorsa ve bu dönem süreye sığmıyorsa sorun zamanlamadır.'),
  ('"Teknoloji bağımlılığı akademik başarıyı düşürür mü?" sorusunda "akademik başarı" için hangi tanım en ölçülebilir olanıdır?', 'Dönem sonu not ortalaması', ['Öğrencinin kendini ne kadar başarılı hissettiği', 'Öğretmenlerin öğrenci hakkındaki genel izlenimleri', 'Öğrencinin gelecekte iyi bir mesleğe sahip olma olasılığı'], 'Not ortalaması herkes için aynı biçimde kaydedilen sayısal bir göstergedir. Öteki seçenekler öznel ya da gelecekteki, ölçülemeyen durumlardır.'),
  ('Bir araştırma sorusunda geçen "sağlıklı beslenme" ifadesi için aşağıdakilerden hangisi işlevsel tanıma en yakındır?', 'Günde en az beş porsiyon sebze ve meyve tüketmek', ['Vücuda iyi gelen yiyecekleri tercih etmeye özen göstermek', 'Aileden öğrenilen geleneksel yemek alışkanlığını sürdürmek', 'Doktorların uygun gördüğü biçimde dengeli yemek yemek'], 'İşlevsel tanım, kavramın nasıl gözlenip sayılacağını belirtir. "Beş porsiyon" sayılabilir bir ölçüttür; ötekiler yoruma açıktır.'),
  ('"Şehirli" kavramını işlevselleştirmek için hangi seçenek en az belirsizlik içerir?', 'Nüfusu 20.000\'in üzerindeki bir yerleşimde yaşamak', ['Kentli yaşam biçimini benimsemiş olmak', 'Modern ve çağdaş bir yaşam sürmek', 'Köyden uzakta, kalabalık ve gürültülü bir yerde oturuyor olmak'], 'Sayısal bir nüfus eşiği herkes için aynı biçimde uygulanır. Ötekiler kişiden kişiye değişen yorumlara açıktır.'),
  ('Bir hipotezin temel öğelerinden biri DEĞİLDİR?', 'Araştırmacının adı ve unvanı', ['İncelenen değişkenler', 'Değişkenler arasında beklenen ilişki', 'Hipotezin geçerli olduğu grup ya da koşul'], 'Hipotez değişkenleri, aralarındaki beklenen ilişkiyi ve hangi grup için öne sürüldüğünü içerir. Araştırmacının kimliği hipotezin parçası değildir.'),
  ('"9. sınıf öğrencilerinde, günde 30 dakikadan fazla sesli okuma yapanların okuma akıcılığı puanı daha yüksektir." Bu hipotezde kapsam (grup) bilgisi hangisidir?', 'Dokuzuncu sınıfa giden öğrenciler', ['Günlük sesli okuma süresi', 'Okuma akıcılığı puanı', 'Günde 30 dakikadan fazla'], 'Hipotezin geçerli sayıldığı grup 9. sınıf öğrencileridir. Sesli okuma süresi bağımsız, akıcılık puanı bağımlı değişkendir.'),
  ('"Işık şiddeti suda yaşayan bitkinin oksijen üretimini etkiler." hipotezi hangi öğe eklenerek daha bilgilendirici olur?', 'Etkinin yönü', ['Bitkinin Latince adının yazım biçimi', 'Deneyin yapılacağı günün adı', 'Kullanılacak kalemin rengi'], 'Hipotez etkinin olacağını söylüyor ama artış mı azalış mı beklendiğini belirtmiyor. Yön eklemek, örneğin "ışık arttıkça üretim artar", hipotezi daha keskin sınanabilir kılar.'),
  ('"Okulumuzda öğrenciler daha az şekerli içecek tüketirse..." diye başlayan bir hipotezin eksik kalan kısmı neyi içermelidir?', 'Ölçülebilir bir beklenen sonucu', ['İçeceklerin üretici firmasının adını', 'Araştırmacının kişisel deneyimini', 'Okulun adresini'], '"Eğer-ise" kalıbının ikinci kısmı, bağımsız değişkendeki değişikliğin hangi ölçülebilir sonucu doğuracağını belirtmelidir.'),
  ('"Ders çalışma süresi ile sınav puanı arasında pozitif bir ilişki vardır." hipotezini "eğer-ise" kalıbına çeviren seçenek hangisidir?', 'Eğer çalışma süresi artarsa sınav puanı da yükselir.', ['Eğer sınav puanı yükselirse öğrencinin çalışma süresi de azalır.', 'Eğer öğrenci çalışmazsa sınava giremez.', 'Eğer sınav kolaysa herkes yüksek puan alır.'], 'Pozitif ilişki iki değişkenin aynı yönde değişmesi demektir; doğru seçenek bunu koşul-sonuç biçiminde ifade eder.'),
  ('Bir hipotezin sorun cümlesi biçiminde değil, bildirme cümlesi biçiminde yazılmasının nedeni nedir?', 'Sınanacak bir iddia ortaya koyması gerektiği için', ['Türkçe dil bilgisinde soru cümlesi yazmak zor olduğu için', 'Okurların soru işaretinden hoşlanmadığı için', 'Bildirme cümleleri her zaman doğru olduğu için'], 'Araştırma sorusu yanıt arar; hipotez ise o soruya önerilen geçici yanıttır ve veriyle sınanacak bir iddia olarak bildirme biçiminde yazılır.'),
  ('"H0: μ = 12, H1: μ > 12" hipotez çiftinde araştırmacının beklentisi nedir?', 'Ortalamanın 12\'den büyük olduğu', ['Ortalamanın tam olarak 12 olduğu', 'Ortalamanın 12\'den küçük olduğu', 'Ortalamanın 12\'den farklı olduğu, yön önemsenmeden'], 'Araştırmacının savı alternatif hipotezde yer alır; burada ortalamanın 12\'yi aştığı beklenmektedir.'),
  ('Aşağıdaki ifadelerden hangisi hipotez değil, bir gözlem bildirimidir?', 'Bu sabah bahçedeki termometre 4°C gösterdi.', ['Hava sıcaklığı düştükçe çiçeklerin açma oranı azalır.', 'Gece sıcaklığı 5°C\'nin altına inerse fesleğen yaprakları kararır.', 'Soğuk havada arıların kovan dışında geçirdiği süre kısalır.'], 'Gözlem bildirimi belirli bir anda neyin görüldüğünü bildirir; genel bir ilişki ya da sınanacak bir beklenti ileri sürmez.'),
  ('Sayıltı ile hipotez arasındaki temel fark nedir?', 'Sayıltı sınanmadan kabul edilir, hipotez ise sınanır', ['Sayıltı bulgulardan sonra yazılır, hipotez önce yazılır', 'Sayıltı her zaman sayısal bir ifadedir', 'Hipotez hiçbir zaman yanlış çıkamaz'], 'Araştırma sayıltıların doğru olduğu kabulüyle yürür; hipotezler ise araştırmanın asıl sınama nesnesidir.'),
  ('"Bu araştırma 2024-2025 öğretim yılında Bursa\'daki iki devlet lisesinin 10. sınıf öğrencileriyle sınırlıdır." ifadesi araştırma önerisinin hangi bölümüne aittir?', 'Sınırlılıklar', ['Sayıltılar', 'Hipotezler', 'Problem durumu'], 'Sınırlılıklar, çalışmanın kapsamını ve sonuçların hangi koşullarla bağlı olduğunu açıkça belirtir.'),
  ('Bir araştırmacının sınırlılıkları açıkça yazması okura en çok ne sağlar?', 'Bulguların hangi koşullarda geçerli olduğunu doğru yorumlamayı', ['Araştırmanın daha az sayfa tutmasını', 'Hipotezlerin kesinlikle doğrulanmasını', 'Örneklemin daha büyük görünmesini'], 'Sınırlılıklar, okurun bulguları uygun olmayan gruplara ya da koşullara genellemesini önler.'),
  ('Bir belediye yalnızca "Mahallemizde kaç sokak hayvanı yaşıyor?" sorusunu yanıtlamak için sayım yapacaktır. Bu çalışmada hipotez kurmak için hangisi söylenebilir?', 'Sayım betimsel olduğundan sınanacak bir ilişki hipotezi gerekmez', ['Sayım ancak yönlü bir hipotezle yapılabilir', 'Hipotez kurulmazsa sayım geçersiz olur', 'Her çalışmada en az üç hipotez bulunmalıdır'], 'Betimsel çalışmalar bir durumu ortaya koyar; değişkenler arası ilişki ya da fark sınanmıyorsa hipotez yerine araştırma soruları yeterlidir.'),
  ('"Okul türü (fen lisesi, Anadolu lisesi, meslek lisesi) öğrencilerin okuma süresini etkiler." hipotezinde okul türü değişkeni kaç kategori içerir?', '3', ['2', '1', '4'], 'Parantez içinde üç ayrı okul türü sayılmıştır; okul türü üç kategorili bir değişkendir.'),
  ('"Ders çalışma süresi arttıkça sınav puanı düşer." hipotezi hangi ilişki türünü öngörür?', 'Negatif ilişki', ['Pozitif ilişki', 'İlişkisizlik', 'Eğrisel ilişki'], 'Bir değişken artarken ötekinin azalması negatif (ters yönlü) ilişkidir. Hipotezin gerçekçi olup olmaması ayrı bir sorudur; burada yalnız öngörülen yön sorulmaktadır.'),
  ('Pozitif ilişki öngören bir hipotez için hangi örnek uygundur?', 'Günlük adım sayısı arttıkça harcanan enerji artar.', ['Gürültü arttıkça okuma hızı azalır.', 'Rakım arttıkça hava sıcaklığı düşer.', 'Sıcaklık arttıkça kar örtüsünün kalınlığı azalır ve erimeler hızlanır.'], 'Pozitif ilişkide iki değişken aynı yönde değişir: adım sayısı da enerji harcaması da birlikte artar.'),
  ('"Fiziksel egzersiz, uyku kalitesini iyileştirerek ertesi günkü dikkat performansını artırır." hipotezinde "uyku kalitesi" hangi roldedir?', 'Aracı', ['Düzenleyici', 'Bağımsız', 'Kontrol'], 'Hipotez egzersizin dikkati uyku kalitesi yoluyla etkilediğini söyler; aradaki bu basamak aracı değişkendir.'),
  ('Bir araştırmacı "Daha çok kütüphanesi olan illerde okuma oranı daha yüksektir." hipotezini il düzeyindeki verilerle sınıyor. Bu hipotezin analiz birimi nedir?', 'İl', ['Öğrenci', 'Kütüphane çalışanı', 'Kitap'], 'Her gözlem bir ile aittir: il başına kütüphane sayısı ve il genelindeki okuma oranı. Analiz birimi ildir.'),
  ('Bir hipotezin analiz birimini önceden belirlemek neden önemlidir?', 'Hangi verinin hangi düzeyde toplanacağını belirler', ['Raporun başlığını kısaltır', 'Katılımcıların kimlik bilgilerinin gizliliğini kendiliğinden sağlar', 'Hipotezin doğru çıkmasını garanti altına alır'], 'Analiz birimi birey, sınıf, okul ya da ülke olabilir; bu seçim örneklemi, veri toplama biçimini ve yapılabilecek çıkarımları belirler.'),
  ('"2010-2020 yılları arasında Van Gölü\'nün yüzey alanı nasıl değişti?" sorusunda kapsamı belirleyen öğeler hangileridir?', 'Yer ve zaman aralığı', ['Yalnızca yöntem', 'Katılımcıların yaşı ve cinsiyeti', 'Ölçme aracının güvenirliği'], 'Soru incelenecek yeri (Van Gölü) ve dönemi (2010-2020) açıkça sınırlar.'),
  ('Bir öğrenci önceki çalışmaları okurken hepsinin büyük kentlerde yapıldığını, kırsal okullarda hiç çalışılmadığını fark ediyor. Bu gözlem en çok neye kaynaklık edebilir?', 'Kırsal okullara yönelik yeni bir araştırma sorusuna', ['Önceki çalışmaların tümünün sahte olduğu sonucuna', 'Konunun artık araştırılamayacağı kararına', 'Büyük kentlerdeki sonuçların doğrudan kırsala uygulanmasına'], 'Alanyazında incelenmemiş bir grup ya da ortam, yeni bir araştırma sorusu için açık bir boşluktur.'),
  ('Bir öğrenci okuduğu makalenin sonunda "Bu bulguların ilkokul öğrencilerinde de geçerli olup olmadığı araştırılmalıdır." cümlesini görüyor. Bu cümle makalenin hangi işlevini yerine getirir?', 'Gelecek araştırmalar için öneri sunar', ['Çalışmanın yöntemini betimler', 'Katılımcıların gizliliğini korur', 'Kaynakçada eksik kalan eserleri tamamlar'], 'Makalelerin "öneriler" ya da "gelecek çalışmalar" kısmı, yazarların gördüğü boşlukları gösterir ve yeni sorular için iyi bir başlangıçtır.'),
  ('Bir kuramdan hipotez türetirken izlenen akıl yürütme hangisidir?', 'Genel önermeden özel bir beklentiye varma', ['Tek bir gözlemden yola çıkarak genel bir yasaya varma', 'Verileri görmeden sonucu yazma', 'Rastgele bir tahmin yapma'], 'Kuram genel bir açıklamadır; ondan, belirli bir durumda neyin gözleneceğine ilişkin özel bir beklenti çıkarılır.'),
  ('Bir öğrenci sabah okul yolunda her gün aynı sokakta kedilerin güneşli duvar dibinde toplandığını görüyor. Bu gözlemden türetilen hipotez hangisidir?', 'Kediler serin sabahlarda güneş alan yerleri tercih eder.', ['Kediler sokaktaki insanları sevdikleri için orada toplanır.', 'Bu kediler başka hiçbir yerde görülmez.', 'Kediler her mevsim ve her saatte hep aynı duvar dibinde bulunur.'], 'Gözlemlenen düzenlilikten (güneşli yer, sabah) genel ve sınanabilir bir açıklama çıkarmak tümevarımla hipotez üretmektir.'),
  ('Gözlemden hipotez üretme sürecinde ilk adım hangisidir?', 'Bir düzenlilik ya da beklenmedik bir durum fark etmek', ['Sonucu rapor olarak yazmak', 'İstatistik testi seçmek', 'Hipotezi desteklemeyen verileri ayıklamak ve geri kalanını saklamak'], 'Hipotez çoğunlukla dikkat çekici bir gözlemle başlar; bu gözlem "neden böyle?" sorusunu doğurur.'),
  ('Bir sınıfta öğrencilerin öğleden sonra derslerinde daha çok esnediği görülüyor. Hangisi bu gözlem için akla gelebilecek rakip açıklamalardan biri DEĞİLDİR?', 'Esnemenin sınıfın kapı numarasıyla ilgili olması', ['Öğle yemeğinden sonra yorgunluk', 'Sınıfın havasının ağırlaşması', 'Öğleden sonraki derslerin daha az etkinlik içermesi'], 'Rakip açıklamalar akla yatkın ve sınanabilir mekanizmalar olmalıdır. Kapı numarası ile esneme arasında makul bir bağ kurulamaz.'),
  ('Bir öğrenci "Kalın kazak giyen öğrencilerin üşüme şikâyeti azdır" hipotezini sınamak istiyor. Hangi veri en doğrudan kanıtı sağlar?', 'Kazak kalınlığı ile üşüme bildiriminin aynı öğrencilerden toplanması', ['Okulun ısıtma faturası', 'Kazakların hangi mağazadan alındığı', 'Öğrencilerin en sevdiği renk ve kazaklarının rengi'], 'Hipotezdeki iki değişken aynı birimlerde ölçülmeden ilişki sınanamaz.'),
  ('"Okul bahçesindeki ağaçların gölgesi, altındaki toprağın nemini artırır." hipotezini sınamak için hangi karşılaştırma gereklidir?', 'Gölgeli ve güneşli noktalardaki toprak nemi', ['Bahçedeki ağaç türlerinin adları', 'Gölgeli alanda oturan öğrenci sayısı', 'Ağaçların dikildiği yıl ve hangi fidanlıktan getirildikleri'], 'Hipotez gölgenin nem üzerindeki etkisini öne sürer; bu ancak gölgeli ve gölgesiz yerlerin nem değerleri karşılaştırılarak sınanır.'),
  ('"Kuşlar kentin gürültülü bölgelerinde daha yüksek frekanslı öter." hipotezini sınamak için hangi ölçüm çifti gereklidir?', 'Ortam gürültüsü düzeyi ve ötüş frekansı', ['Kuşların kanat açıklığı ve ağırlığı', 'Kentin nüfusu ve yüzölçümü', 'Ağaçların boyu ve yaprak sayısı ile kuşların yuva sayısı'], 'Hipotezdeki iki değişken gürültü ve ötüş frekansıdır; her kayıt noktasında ikisi birlikte ölçülmelidir.'),
  ('Hipotez: "Tuzlu suda bekletilen salatalık dilimleri kütle kaybeder." Hangi sonuç bu hipotezi çürütür?', 'Dilimlerin kütlesi artar ya da değişmez', ['Dilimlerin kütlesi azalır', 'Dilimler biraz yumuşar ve küçülür', 'Dilimler tuzlu suda kütle kaybeder, saf suda kaybetmez'], 'Hipotez kütle kaybı öngörür; kütlenin artması ya da hiç değişmemesi bu öngörüyle çelişir.'),
  ('"Aspirin baş ağrısını 30 dakika içinde hafifletir." hipotezini çürütecek sonuç için hangi ölçüm gereklidir?', 'Aspirin alımından 30 dakika sonra ağrı düzeyi', ['Aspirinin üretildiği tarih', 'Hastanın aspirin almadan önceki gün ne yediği', 'Aspirin kutusunun rengi ve kutudaki tablet sayısı'], 'Hipotezin öngörüsü 30 dakika içindeki ağrı değişimiyle ilgilidir; bu zaman noktasındaki ağrı düzeyi ölçülmeden hipotez yanlışlanamaz.'),
  ('Bir araştırmanın sonucunda sıfır hipotezi reddedilmiş ve yönlü hipotezle tutarlı bir fark bulunmuştur. Raporda en uygun ifade hangisidir?', 'Bulgular hipotezi desteklemektedir.', ['Hipotez kesin olarak kanıtlanmıştır.', 'Hipotez her koşulda geçerli bir yasa olmuştur.', 'Bu sonuçla konu tamamen kapanmıştır ve başka çalışmaya gerek yoktur.'], 'Tek bir çalışma hipotezi kanıtlamaz; tutarlı bir bulgu onu destekler. Bilimsel dil bu kesinlik düzeyini yansıtmalıdır.'),
  ('Bir öğrenci "Hipotezim yanlış çıktı, bu yüzden araştırmam başarısız oldu." diyor. Öğretmeninin en uygun yanıtı hangisidir?', 'Desteklenmeyen bir hipotez de bilgi üretir; nedenlerini tartışmalısın', ['Haklısın, verileri değiştirerek hipotezi tutturmalısın', 'Hipotezi sonuca göre yeniden yazıp başından beri öyle olduğunu söylemelisin', 'Raporu hiç yazmamalısın ve konuyu bırakmalısın'], 'Beklenen sonucun çıkmaması, neyin doğru olmadığını gösterir; bu sonuç dürüstçe raporlanıp olası nedenleri tartışılmalıdır.'),
  ('Hangi ifade ilişkisel bir çalışmanın sonucunu raporlarken uygun DEĞİLDİR?', 'X, Y\'ye yol açmaktadır.', ['X ile Y arasında pozitif bir ilişki bulunmuştur.', 'X\'i yüksek olanların Y\'si de yüksektir.', 'X ve Y birlikte değişmektedir.'], '"Yol açmak" nedensellik bildirir; ilişkisel desen bu iddiayı tek başına desteklemez.'),
  ('Aşağıdaki hipotezlerden hangisi tek bir sınanabilir iddia içerir?', 'Günlük şeker tüketimi arttıkça diş çürüğü sayısı artar.', ['Şeker diş çürüğünü artırır ve kilo almaya neden olur.', 'Şekerli ve asitli içecekler dişlere ve mideye zarar verir.', 'Şeker tüketimi azalırsa hem diş sağlığı hem de uyku kalitesi iyileşir ve sınav başarısı artar.'], 'Doğru seçenek bir bağımsız ve bir bağımlı değişken arasındaki tek ilişkiyi belirtir; ötekiler birden çok iddiayı birleştirir.'),
  ('Bir fen projesi sorusunun "sınanabilir" olması ne demektir?', 'Deney ya da gözlemle toplanan veriyle yanıtlanabilmesi', ['Kitaplarda yanıtının yazılı olması', 'Öğretmen tarafından onaylanmış olması', 'Yanıtının herkes tarafından önceden tahmin edilebilmesi ve tartışma yaratmaması'], 'Sınanabilir soru, araştırmacının kendisinin toplayabileceği verilerle yanıtlanabilir.'),
  ('Bir öğrenci sabun köpüğünün ömrünü merak ediyor. Hangisi bu merakı bir fen projesi sorusuna en iyi dönüştürür?', 'Sabunlu suya eklenen gliserin miktarı köpüğün patlama süresini nasıl etkiler?', ['Köpükler neden güzel görünür?', 'Köpükler hangi renktedir?', 'Sabun köpüğü yapmanın en eğlenceli yolu nedir ve çocuklar neden sever?'], 'Doğru seçenek bağımsız değişkeni (gliserin miktarı) ve ölçülebilir bağımlı değişkeni (patlama süresi) birlikte verir.'),
  ('Nitel bir araştırma sorusunu en iyi yansıtan seçenek hangisidir?', 'Görme engelli öğrenciler okul kütüphanesini kullanırken neler yaşıyor?', ['Görme engelli öğrencilerin kaç yüzdesi kütüphaneye gidiyor?', 'Kütüphane kullanımı not ortalamasıyla ilişkili mi?', 'Görme engelli öğrencilerin kütüphanede geçirdiği ortalama süre kaç dakikadır ve bu süre yaşa göre değişir mi?'], 'Nitel sorular deneyimi, anlamı ve süreci anlamaya çalışır; "neler yaşıyor" sorusu bunu hedefler. Öteki seçenekler sayısal yanıt ister.'),
  ('"Bir köyde imece geleneğinin bugün nasıl sürdürüldüğü" sorusunu inceleyen bir araştırmacı hangi tür soruyla çalışmaktadır?', 'Bir topluluğun pratiğini anlamaya yönelik nitel soru', ['İki değişken arasındaki korelasyonu soran nicel soru', 'Bir müdahalenin etkisini sınayan deneysel soru', 'Bir evren ortalamasını kestirmeye yönelik betimsel istatistik sorusu'], 'Soru bir geleneğin günümüzdeki işleyişini anlamaya çalışır; gözlem ve görüşmeyle incelenen nitel bir sorudur.'),
  ('"İlçemizdeki lise öğrencilerinin yüzde kaçı düzenli kahvaltı yapıyor?" sorusu için en uygun veri toplama yolu hangisidir?', 'Temsilî bir öğrenci örneklemine kısa anket uygulamak', ['Üç öğrenciyle derinlemesine görüşmek', 'Kahvaltının etkisini sınayan bir deney yapmak', 'Okul müdürüne öğrencilerin kahvaltı alışkanlıklarını tahmin edip etmediğini sormak'], 'Oran soran betimsel bir soru, evreni temsil eden bir örneklemden toplanan anket verisiyle yanıtlanır.'),
  ('"Yeni bir okuma programı öğrencilerin okuma hızını artırır mı?" sorusu en uygun biçimde hangi desenle yanıtlanır?', 'Programın uygulandığı ve uygulanmadığı grupların karşılaştırıldığı deneysel desen', ['Tek bir öğrencinin günlüğünün incelenmesi', 'Okuma hızının yalnızca bir kez ölçüldüğü tarama', 'Öğretmenlerin programla ilgili görüşlerinin toplandığı odak grup ve sonrasında yapılan sohbet'], 'Bir uygulamanın etkisini soran nedensel sorular, karşılaştırma grubu içeren deneysel ya da yarı deneysel desenlerle yanıtlanır.'),
  ('"Boy uzunluğu ile ayakkabı numarası arasında ilişki var mı?" sorusunu yanıtlamak için hangi çözümleme uygundur?', 'İki değişken arasındaki korelasyonun hesaplanması', ['Bir grubun ortalama boyunun hesaplanması', 'Katılımcılarla ayakkabı tercihleri üzerine görüşme', 'Boyun bir ilaçla değiştirildiği bir deney tasarlanması ve uygulanması'], 'İki sürekli değişken arasındaki ilişkiyi soran bir soru korelasyon çözümlemesiyle yanıtlanır.'),
  ('Bir araştırma sorusu ile seçilen yöntem uyuşmazsa ne olur?', 'Toplanan veri soruyu yanıtlamaya yetmez', ['Araştırma daha hızlı biter', 'Sonuçlar daha genellenebilir olur', 'Hipotez kendiliğinden desteklenir ve rapor daha ikna edici olur'], 'Örneğin nedensel bir soruyu yalnız anketle yanıtlamaya çalışmak, ilişkiyi gösterir ama nedenselliği gösteremez; soru yanıtsız kalır.'),
  ('El feneriniz yanmıyor. Bilimsel bir sorun giderme yaklaşımına göre ilk adım hangisidir?', 'Olası nedenleri sıralayıp her birini sınayacak bir hipotez kurmak', ['El fenerini hemen atıp yenisini almak', 'Feneri sallayıp düzelmesini beklemek', 'Arkadaşlarına sorup en çok söylenen nedeni kesin kabul etmek'], 'Pil bitmiş olabilir, ampul yanmış olabilir, bağlantı kopmuş olabilir. Her biri bir hipotezdir ve sırayla sınanarak gerçek neden bulunur.'),
  ('Bir öğrenci "El feneri pil bittiği için yanmıyor." hipotezini kuruyor. Bu hipotezi en doğrudan nasıl sınar?', 'Yeni pil takıp fenerin yanıp yanmadığına bakar', ['Ampulü değiştirir', 'Feneri başka bir odaya götürür', 'Fenerin rengine bakar ve markasını internette araştırır'], 'Hipotezde yalnız pil değişkeni öne sürülmüştür; yalnız pili değiştirmek bu hipotezi öteki olasılıklardan ayırarak sınar.'),
  ('Evdeki saksı çiçeğinin yaprakları sararıyor. Aşağıdakilerden hangisi sınanabilir bir hipotez olarak en iyi ifade edilmiştir?', 'Saksı fazla sulandığı için kökler havasız kalıyor; sulama azaltılırsa yeni yapraklar yeşil çıkar.', ['Çiçek mutsuz olduğu için sararıyor.', 'Çiçek kötü şans getirdiği için sararıyor.', 'Çiçeğin sararması doğanın gizemli bir döngüsüdür ve açıklanamaz; kendi hâline bırakılmalıdır.'], 'Doğru seçenek bir neden önerir ve o neden ortadan kaldırıldığında ne gözleneceğini söyler; böylece sınanabilir.'),
  ('Bir öğrencinin hipotezi "Gölgede bekletilen suyun sıcaklığı, güneşte bekletilenden en az 5°C düşük kalır." biçimindedir. Ölçümlerde güneşteki su 31°C, gölgedeki 27°C bulunmuştur. Sonuç nasıl yorumlanır?', 'Fark 4°C olduğundan hipotezdeki eşik karşılanmamıştır', ['Fark 4°C olduğundan hipotez desteklenmiştir', 'Fark 58°C olduğundan hipotez desteklenmiştir', 'Gölgedeki su daha sıcak olduğu için hipotez ters yönde desteklenmiştir'], '31 − 27 = 4°C. Gölgedeki su daha serin olsa da hipotez en az 5°C fark öngördüğü için bu eşik tutmamıştır.'),
  ('Bir araştırmacı hipotezini "Hastaların en az %25\'i iyileşecektir." diye yazıyor. Çalışmaya 80 hasta katılacaksa hipotezin desteklenmesi için en az kaç hastanın iyileşmesi gerekir?', '20', ['25', '8', '55'], '80 hastanın %25\'i 80 × 0,25 = 20\'dir. En az 20 hasta iyileşirse hipotezdeki oran sağlanır.'),
  ('Bir öğrenci "Fasulye fideleri 12 günde ortalama 1,5 katına uzar." hipotezini kuruyor. Fidelerin başlangıç boyu ortalama 12 cm ise hipotezin öngördüğü ortalama boy kaç cm\'dir?', '18', ['13,5', '24', '6'], '1,5 katına uzamak, boyun 12 × 1,5 = 18 cm olması demektir.'),
  ('Hipotez: "Nem, ekmeğin küflenmesini hızlandırır." Aşağıdaki tahminlerden hangisi bu hipotezden doğru biçimde türetilmiştir?', 'Nemli bezle sarılmış dilim, kuru kapta tutulandan daha önce küflenecektir.', ['Ekmek dilimleri bir hafta içinde kuruyacaktır.', 'Kuru kaptaki dilim, nemli bezdekinden önce küflenecektir.', 'Nemli bezle sarılan dilimin rengi ve tadı hiçbir biçimde değişmeyecek ve uzun süre taze kalacaktır.'], 'Hipotez nem arttıkça küflenmenin hızlandığını söyler; nemli koşuldaki dilimin daha önce küflenmesi beklenir.'),
  ('Bir tahmin "Eğer hipotez doğruysa, X yapıldığında Y gözlenir" kalıbıyla yazılır. Bu kalıpta "X yapıldığında" kısmı neyi anlatır?', 'Deneyde uygulanacak işlemi ya da koşulu', ['Hipotezin kimin tarafından yazıldığını', 'Sonuçların hangi dergide yayımlanacağını', 'Bağımlı değişkenin ölçüleceği birimi ve aracı'], '"X yapıldığında" araştırmacının düzenlediği işlemdir; "Y gözlenir" ise beklenen ölçülebilir sonuçtur.'),
  ('Aşağıdakilerden hangisi iyi bir hipotezin özelliklerinden biri DEĞİLDİR?', 'Olası her sonuçla uyumlu olması', ['Açık ve anlaşılır dille yazılması', 'Sınanabilir olması', 'Önceki bilgilerle bağlantılı olması'], 'Her sonuçla uyumlu olan bir hipotez yanlışlanamaz; bu bir üstünlük değil, ciddi bir zayıflıktır.'),
  ('İki öğrenci hipotez yazıyor. A: "Rüzgâr hızı arttıkça çamaşırlar daha çabuk kurur." B: "Çamaşırların kuruması birçok şeye bağlıdır." Hangisi neden daha iyidir?', 'A; belirli bir ilişki öne sürer ve sınanabilir', ['B; daha çok etkeni kapsar', 'İkisi eşittir; ikisi de çamaşırla ilgilidir', 'B; çünkü daha az iddialı olduğu için yanlış çıkma olasılığı yoktur'], 'B doğru olsa bile hiçbir şeyi sınamaya açmaz. A ise hangi sonucun kendisini çürüteceğini belirler.'),
  ('Bir hipotez: "Okulda telefon yasağı uygulanan sınıflarda teneffüste yüz yüze sohbet süresi daha uzundur." Bu hipotezin yanıt aradığı araştırma sorusu hangisidir?', 'Telefon yasağı teneffüsteki yüz yüze sohbet süresini etkiler mi?', ['Öğrencilerin kaçının telefonu var?', 'Telefon yasağı okullarda nasıl ve kimler tarafından uygulanmalıdır?', 'Teneffüs süresi ne kadar olmalı ve kaç dakikaya çıkarılmalıdır?'], 'Hipotez, telefon yasağı ile sohbet süresi arasındaki ilişkiye ilişkin bir yanıt önerir; soru da bu ilişkiyi sormalıdır.'),
  ('Bir araştırma sorusu yazılmadan önce yapılan kısa ön gözlemlerin temel amacı nedir?', 'Sorunun gerçekten var olup olmadığını ve neye odaklanılacağını görmek', ['Hipotezi kesin olarak kanıtlamak', 'Asıl verilerin yerine geçmek', 'Araştırmayı uzatmak ve rapora ek sayfa kazandırarak daha kapsamlı görünmesini sağlamak'], 'Ön gözlemler, sorunun boyutunu ve hangi değişkenlerin öne çıktığını gösterir; böylece soru gerçek duruma uygun biçimde yazılır.'),
  ('Bir öğrenci "Bütün metaller ısıtılınca genleşir." önermesini sınamak için yalnızca demir ve bakır çubuk kullanıyor. Bu sınama için en doğru değerlendirme hangisidir?', 'Önermeyi destekler ama bütün metaller için kesinleştirmez', ['Önermeyi kesin olarak kanıtlar', 'Önermeyle ilgisi yoktur, çünkü yalnızca iki çubuk ısıtılmıştır', 'Önermeyi çürütür çünkü yalnızca iki metal denenmiştir'], 'İki olumlu örnek önermeyle tutarlıdır; ancak denenmemiş metaller için bir şey söylemez. Genel önerme ancak desteklenmiş sayılır.'),
  ('Bir hipotezin "hava sıcaklığı arttıkça dondurma satışları artar" biçiminde yazılması ile "dondurma satışları hava sıcaklığına bağlıdır" biçiminde yazılması arasındaki fark nedir?', 'Birincisi ilişkinin yönünü de belirtir', ['İkincisi daha kesin ve yönlüdür', 'İki ifade aynı ölçüde kesindir', 'Birincisi bir sıfır hipotezi, ikincisi ise alternatif hipotezdir'], '"Bağlıdır" ifadesi bir ilişki olduğunu söyler ama hangi yönde olduğunu belirtmez; birinci ifade yönlü bir hipotezdir.'),
  ('"Kahve içen ve içmeyen öğrencilerin uyku süreleri farklıdır." araştırma hipotezini sınamak için hangi karşılaştırma yapılır?', 'İki ayrı grubun ortalama uyku süreleri', ['Aynı kişinin kahveden önceki ve sonraki nabzı', 'Kahve tüketimi ile boy arasındaki korelasyon', 'Tek bir grubun uyku süresinin sabit bir değerle karşılaştırılması ve oranlanması'], 'Hipotez önceden var olan iki grubu (içen/içmeyen) karşılaştırır; iki bağımsız grubun ortalamaları karşılaştırılır.'),
  ('Mahalle sakinleri okul önündeki yaya geçidinde sık sık kaza tehlikesi yaşandığından yakınıyor. Bu yakınmayı veriyle yanıtlanabilir bir araştırma sorusuna en iyi dönüştüren seçenek hangisidir?', 'Okul giriş ve çıkış saatlerinde yaya geçidinde durmayan araç oranı nedir?', ['Sürücüler neden bu kadar dikkatsiz?', 'Yaya geçidine trafik polisi konmalı mı?', 'Belediye bu konuda neden hiçbir şey yapmıyor ve sorumluluğu kimin üstüne atıyor?'], 'Doğru seçenek gözlemle ölçülebilir bir göstergeyi (durmayan araç oranı) ve zamanı (giriş-çıkış saatleri) belirtir.'),
  ('Gazetecilikte kullanılan "5N1K" (ne, nerede, ne zaman, nasıl, neden, kim) soruları araştırma sorusu yazarken nasıl yararlı olur?', 'Sorunun kapsamını belirleyen öğeleri tek tek gözden geçirmeyi sağlar', ['Her araştırma sorusunun altı soru cümlesinden oluşmasını zorunlu kılar', 'Araştırma sorusunun yerine geçer', 'Araştırma sorusunu hipoteze dönüştürür ve istatistik testini seçer'], 'Bu sorular kimin, nerede, ne zaman, neyin inceleneceğini netleştirmeye yardım eder; ancak hepsi tek bir soruya sıkıştırılmak zorunda değildir.'),
  ('"Ankara\'daki ortaokul öğrencileri" ifadesi bir araştırma sorusunda 5N1K öğelerinden hangilerini karşılar?', 'Kim ve nerede', ['Ne zaman ve nasıl', 'Neden ve ne', 'Nasıl ve kim'], '"Ortaokul öğrencileri" kimin inceleneceğini, "Ankara" ise nerede inceleneceğini belirtir.'),
  ('Aşağıdakilerden hangisi bir hipotez cümlesi değildir?', 'Lütfen deney sonuçlarını tabloya kaydediniz.', ['Işık şiddeti arttıkça yaprakların açılma süresi kısalır.', 'Tuz oranı yüksek toprakta çimlenme oranı düşüktür.', 'Ses düzeyi arttıkça öğrencilerin hata sayısı artar.'], 'Doğru seçenek bir yönergedir; hiçbir ilişki ya da beklenti öne sürmez. Öteki seçenekler sınanabilir ilişkiler bildirir.'),
  ('"Bence müzik dersleri çok eğlencelidir." cümlesi neden bir hipotez sayılmaz?', 'Kişisel bir görüş bildirir, sınanacak bir ilişki öne sürmez', ['Çok kısa olduğu için', 'Müzik bilimsel olarak incelenemediği için', 'Hipotezler yalnızca fen derslerinde kurulabildiği için bu alanda geçerli olamaz'], 'Hipotez, değişkenler arasında sınanabilir bir ilişki önerir. Kişisel beğeni bildirmek bir hipotez değildir.'),
  ('Bir araştırmacı "Kentin dört semtinde hava kirliliği düzeyleri farklıdır." hipotezini kuruyor. Bu hipotezin sınanması için en az kaç semtte ölçüm yapılmalıdır?', 'Dört semtin her birinde', ['Yalnızca en kirli semtte', 'Herhangi iki semtte', 'Tek bir semtte, birden çok kez'], 'Hipotez dört semti karşılaştırır; bu yüzden her semtte ölçüm yapılmadan hipotez sınanamaz.'),
  ('Bir araştırma sorusunda gereksiz teknik terimlerin ve uzun yan cümlelerin bulunmasının sakıncası nedir?', 'Sorunun ne sorduğu belirsizleşir', ['Soru daha bilimsel görünür ve bu bir üstünlüktür', 'Soru kendiliğinden hipoteze dönüşür', 'Okurun soruyu ezberlemesi kolaylaşır ve hatırlanır'], 'İyi bir araştırma sorusu kısa, açık ve tek bir odağa sahiptir; gereksiz karmaşıklık neyin araştırılacağını gizler.'),
  ('Aşağıdaki araştırma sorularından hangisi tek bir odağa sahiptir?', 'Gece vardiyasında çalışan hemşirelerin uyku süresi ne kadardır?', ['Hemşirelerin uyku süresi, maaşı, iş doyumu ve aile yaşamı nasıldır?', 'Hemşireler neden yorulur ve bu sağlık sistemini nasıl etkiler?', 'Sağlık çalışanlarının çalışma koşulları, ücretleri ve tükenmişlik düzeyleri birlikte ele alındığında ne gösterir?'], 'Doğru seçenek tek bir grubu ve tek bir değişkeni sorar. Ötekiler birçok ayrı soruyu tek cümlede toplar.'),
  ('Bir öğrenci araştırma sorusunu "Gençlerde kitap okuma" diye yazmıştır. Bu ifadeyi araştırma sorusuna dönüştürmek için en az hangi düzenleme gerekir?', 'Soru biçimine sokup ne sorulduğunu belirtmek', ['Başına "Önemli bir konu:" eklemek', 'İfadeyi büyük harflerle yazmak', 'İfadeyi kısaltıp yalnızca "Okuma" bırakmak ve konuyu genişletmek'], 'Bir ad öbeği konu adıdır; araştırma sorusu neyin, kimde, nasıl inceleneceğini soran bir soru cümlesi olmalıdır.'),
  ('İlkokul öğrencilerine fen etkinliği için verilen "Hangi top daha yükseğe zıplar: tenis topu mu, pinpon topu mu?" sorusu hangi tür araştırma sorusudur?', 'Karşılaştırma sorusu', ['Betimsel sayım sorusu', 'İlişki sorusu', 'Değer yargısı sorusu ve görüş bildirme'], 'Soru iki nesnenin aynı özelliğini karşılaştırır; adil bir karşılaştırma için topların aynı yükseklikten bırakılması gerekir.'),
  ('Bir spor bilimci "Isınma hareketlerinin süresi sprint performansını etkiler mi?" sorusunu inceliyor. Hangi hipotez bu soruya uygun ve sınanabilir bir yanıttır?', '10 dakika ısınan sporcuların 30 m sprint süresi, ısınmayanlardan kısadır.', ['Isınma sporcular için iyidir.', 'Sprint önemli bir spordur.', 'Isınma hareketleri sporcuların motivasyonunu ve takım ruhunu her koşulda geliştirir.'], 'Doğru seçenek ısınma süresini ve ölçülebilir sonucu (30 m sprint süresi) belirtir ve yön öngörür.'),
  ('"Bu bitki çayı bağışıklığı güçlendirir." iddiasını sınanabilir kılan hipotez hangisidir?', 'Sekiz hafta düzenli bu çayı içenler, içmeyenlere göre daha az soğuk algınlığı geçirir.', ['Bu çay doğal olduğu için sağlıklıdır.', 'Bu çay çok eskiden beri içilir.', 'Bu çay insanı içten içe güçlendirir ve kendini iyi hissettirir.'], 'Doğru seçenek süreyi, karşılaştırmayı ve ölçülebilir bir sonucu (soğuk algınlığı sayısı) belirtir.'),
  ('Bir araştırma önerisinde "Tanımlar" bölümünün işlevi nedir?', 'Önemli kavramların bu çalışmada hangi anlamda kullanıldığını belirtmek', ['Kaynakçadaki eserleri alfabetik sıralamak', 'Bulguları özetlemek', 'Araştırmacının özgeçmişini ve daha önce yaptığı çalışmaları tanıtmak'], 'Örneğin "akran zorbalığı" kavramının bu çalışmada nasıl tanımlandığı ve ölçüldüğü belirtilir; böylece okur ile araştırmacı aynı şeyi anlar.'),
  ('Bir deneyde beklenmedik bir sonuç alındığında, bunun yeni bir olgu mu yoksa hata mı olduğunu anlamak için ilk yapılması gereken nedir?', 'Ölçümleri ve düzeneği kontrol edip deneyi yinelemek', ['Sonucu hemen yeni bir buluş olarak duyurmak', 'Sonucu verilerden silmek', 'Hipotezi sonuca uyacak biçimde değiştirip deneyi bir daha yapmamak'], 'Beklenmedik sonuçlar değerli olabilir, ama önce ölçüm hatası ya da düzenek sorunu olup olmadığı yineleme ile sınanmalıdır.'),
  ('Bir öğretmen öğrencilerinden aynı konuda hem araştırma sorusu hem hipotez yazmalarını istiyor. Bir öğrencinin sorusu "Gürültü okuma anlamayı etkiler mi?", hipotezi ise "Gürültülü ortamda okuyanların anlama puanı sessiz ortamda okuyanlardan düşüktür." Bu eşleşme için hangisi doğrudur?', 'Hipotez soruya yönlü ve ölçülebilir bir yanıt önermektedir', ['Hipotez soruyla ilgisizdir', 'Hipotez sorudan daha belirsizdir', 'Hipotez sorunun aynısıdır, yalnızca soru işareti kaldırılmıştır'], 'Soru etkinin varlığını sorar; hipotez bu soruya yön (puan düşer) ve ölçüm (anlama puanı) içeren bir yanıt önerir.'),
  ('Bir araştırmanın "Problem cümlesi" genellikle nasıl yazılır?', 'Çalışmanın yanıt arayacağı temel soruyu tek bir soru cümlesiyle', ['Bulguları özetleyen bir bildirme cümlesiyle', 'Kaynakçadaki ilk eserin adıyla', 'Araştırmacının teşekkür ettiği kişilerin adlarıyla ve kurumlarıyla'], 'Problem cümlesi, problem durumundan süzülen ve çalışmanın bütünüyle yanıtlamaya çalıştığı ana sorudur.'),
  ('"Ortaokul Türkçe ders kitaplarındaki metinlerde kadın ve erkek karakterlerin hangi mesleklerle betimlendiği" sorusu için veri kaynağı nedir?', 'Ders kitaplarının metinleri', ['Öğrencilerle yapılan görüşmeler', 'Öğretmenlerin ders içi gözlemi', 'Kitapları basan yayınevlerinin satış rakamları ve muhasebe kayıtları'], 'Soru belgelerin içeriğini sorar; veri doğrudan ders kitaplarındaki metinlerin incelenmesiyle (içerik çözümlemesi) elde edilir.'),
  ('"Bu köprüyü en az malzemeyle 2 ton taşıyacak biçimde nasıl tasarlarım?" sorusu hangi tür sorudur?', 'Mühendislik tasarım sorusu', ['Betimsel bilimsel soru', 'Felsefi soru', 'Değer yargısı içeren ahlaki soru'], 'Tasarım soruları belirli ölçütleri (2 ton taşıma) ve kısıtları (en az malzeme) karşılayan bir çözüm arar; doğadaki bir ilişkiyi açıklamaya çalışan bilimsel sorulardan farklıdır.'),
  ('"Bir ilacın ağrı kesici etkisi, yaşlı hastalarda gençlere göre daha zayıftır." hipotezinde yaşın rolü nedir?', 'Etkinin gücünü değiştiren düzenleyici değişken', ['İlacın ağrıyı kestiği aracı yol', 'İlacın kendisi', 'Ağrı düzeyinin ölçüm birimi ve ölçüm aracı'], 'Hipotez ilacın etkisinin yaşa göre farklılaştığını öne sürer; yaş düzenleyici rol oynar.'),
  ('"Teneffüste dışarıda oynayan öğrencilerin derse dönüşte dikkat puanı daha yüksektir; bu etki özellikle kalabalık sınıflarda belirgindir." Bu hipotezde "sınıf kalabalığı" hangi roldedir?', 'Düzenleyici', ['Aracı', 'Bağımlı', 'Karıştırıcı ve aynı zamanda bağımlı'], 'Hipotez dışarıda oynamanın etkisinin sınıf kalabalığına göre değiştiğini söyler; kalabalık bu etkinin gücünü düzenler.'),
  ('Bir öğrenci okulundaki 400 öğrenciye anket dağıtacak ve deneyimine göre yanıtlama oranının yaklaşık %25 olacağını kestiriyor. Kaç yanıt beklemelidir?', '100', ['25', '300', '400'], '400 × 0,25 = 100. Analiz için daha fazla yanıt gerekiyorsa bu kestirim soru ya da örneklem planını gözden geçirmeyi gerektirir.'),
  ('Bir öğrenci kuş gözlemi yapacak: 8 farklı noktada, her noktada 25 dakika gözlem. Bir gözlem turu için toplam kaç dakika gözlem süresi gerekir (noktalar arası yürüyüş hariç)?', '200', ['33', '125', '250'], '8 × 25 = 200 dakika, yani yaklaşık 3 saat 20 dakika. Yürüyüş eklendiğinde bir turun yarım günü bulacağı, soru planlanırken hesaba katılmalıdır.'),
  ('"Okulumuzdaki öğrenciler mutlu mu?" sorusunun en belirgin sorunu nedir?', '"Mutlu" kavramının nasıl ölçüleceği belirsizdir', ['Soru bir değer yargısı içerir', 'Soru etik dışıdır', 'Okul öğrencileriyle araştırma yapmak her durumda yasak olduğu için soru geçersizdir'], 'Mutluluk çok farklı biçimlerde anlaşılabilir; bir ölçek ya da açık bir gösterge belirtilmeden soru yanıtlanamaz.'),
  ('"Türkiye\'nin başkenti hangi kenttir?" sorusu neden bir araştırma sorusu olarak uygun değildir?', 'Yanıtı bir başvuru kaynağında hazır bulunur; yeni bir bilgi üretmez', ['Soru coğrafya ile ilgili olduğu için', 'Soru çok uzun olduğu için', 'Soru birden fazla değişken içerdiği ve bunları aynı anda ölçmek gerektiği için'], 'Araştırma sorusu, yanıtı veri toplayıp çözümleyerek bulunan sorudur. Bir ansiklopediden tek adımda bulunan bilgi araştırma gerektirmez.'),
  ('"1950\'lerde yaşamış kişilerin çocukluklarında hangi oyunları oynadığı" konusunda çalışan bir öğrenci, yalnızca 15-18 yaşındaki arkadaşlarıyla görüşmeyi planlıyor. Bu planın sorunu nedir?', 'Veri kaynağı soruyla uyuşmuyor; o dönemi yaşamış kişilere ya da belgelere ulaşılmalı', ['Görüşme bir veri toplama yöntemi değildir', 'Soru çok yenidir', 'Arkadaşlarla görüşmek her zaman daha güvenilir veri sağladığı için plan uygundur'], 'Arkadaşları o dönemi yaşamamıştır; soru, o dönemin tanıklarından ya da dönem belgelerinden veri toplanmasını gerektirir.'),
  ('"Düzenli spor yapan öğrenciler daha başarılıdır." ifadesini hipotez olarak kullanmadan önce hangi düzeltme en gereklidir?', '"Düzenli" ve "başarılı" kavramlarını ölçülebilir biçimde tanımlamak', ['Cümleyi soru cümlesine çevirmek', 'Cümleden "öğrenciler" sözcüğünü çıkarmak', 'Cümlenin sonuna ünlem koyarak beklentinin gücünü vurgulamak'], 'İfade yön içerir ama iki temel kavramı belirsiz bırakır; örneğin "haftada en az 3 gün 30 dakika spor" ve "dönem sonu not ortalaması" gibi tanımlar gerekir.'),
  ('Bir öğrenci fasulye tohumlarını farklı derinliklere ekip çimlenme süresini kaydediyor: 1 cm\'de 5 gün, 3 cm\'de 6 gün, 6 cm\'de 9 gün, 9 cm\'de 13 gün. Bu verilerden en uygun biçimde türetilen hipotez hangisidir?', 'Ekim derinliği arttıkça çimlenmenin toprak yüzeyinde görülmesi gecikir.', ['Ekim derinliği arttıkça çimlenme süresi kısalır.', 'Ekim derinliğinin çimlenme süresine hiçbir etkisi yoktur.', 'Çimlenme süresi yalnızca 3 cm derinlikte değişir, öteki derinliklerde hep aynı kalır.'], 'Derinlik her arttığında süre de uzamıştır; veriler pozitif yönlü bir ilişkiyi düşündürür. Bu hipotez daha çok tohum ve yinelemeyle sınanmalıdır.'),
  ('Bir öğrenci mahallesindeki sokakların ağaç sayısı ile yaz öğle saatindeki asfalt sıcaklığını ölçüyor: 0 ağaç 52°C, 5 ağaç 47°C, 10 ağaç 43°C, 20 ağaç 38°C. En uygun hipotez hangisidir?', 'Sokaktaki ağaç sayısı arttıkça asfalt sıcaklığı düşer.', ['Ağaç sayısı arttıkça asfalt sıcaklığı yükselir.', 'Asfalt sıcaklığı ağaç sayısını belirler.', 'Ağaçlar yalnızca kışın etkilidir, yazın hiçbir etkisi gözlenmez.'], 'Veriler ağaç sayısı ile sıcaklık arasında negatif bir ilişki gösterir. Gölgeleme gibi bir mekanizma önerilebilir, ancak sokakların yönü gibi etkenler de denetlenmelidir.'),
  ('"Kitap okuma alışkanlığı" kavramını bir araştırma sorusunda ölçülebilir kılmak için en uygun gösterge hangisidir?', 'Son üç ayda baştan sona okunan kitap sayısı', ['Kişinin kitapları ne kadar sevdiği', 'Evdeki kitaplığın güzelliği', 'Kişinin kendini kültürlü biri olarak görüp görmediği ve bundan duyduğu gurur'], 'Belirli bir sürede okunan kitap sayısı sayılabilir bir davranış göstergesidir; ötekiler duygu ya da izlenimdir.'),
  ('Bir öğrenci "trafik yoğunluğu"nu araştırma sorusunda kullanacak. Hangisi en ölçülebilir tanımdır?', 'Sabah 8.00-8.15 arasında kavşaktan geçen araç sayısı', ['Sürücülerin trafik hakkında ne düşündüğü', 'Kavşağın ne kadar kalabalık göründüğü', 'Trafiğin insanları ne kadar sinirlendirdiği ve günlerini nasıl etkilediği'], 'Belirli bir zaman aralığında bir noktadan geçen araç sayısı, herkesin aynı biçimde sayabileceği bir göstergedir.'),
  ('Bir kimya öğrencisi "Asit derişimi arttıkça magnezyum şeridin tepkimesi hızlanır." hipotezini kuruyor. Hipotezdeki tepkime hızını ölçmek için en uygun gösterge hangisidir?', 'Şeridin tamamen tükenme süresi', ['Şeridin rengi', 'Asit şişesinin büyüklüğü', 'Laboratuvarın sıcaklığı ve deneyin yapıldığı gün'], 'Şeridin tükenme süresi kısaldıkça tepkime hızlanmış demektir; ölçülebilir ve karşılaştırılabilir bir göstergedir.'),
  ('Gökbilimde "Daha sıcak yıldızlar daha mavi görünür." gibi hipotezler laboratuvar deneyiyle değil, gözlemle sınanır. Bunun nedeni nedir?', 'Yıldızların sıcaklığı araştırmacı tarafından değiştirilemez', ['Yıldızlar hiç gözlenemez', 'Gökbilimde hipotez kurulmaz', 'Gözlem bilimsel bir yöntem sayılmadığı için gökbilimciler ondan kaçınır'], 'Değiştirilemeyen değişkenler için hipotezler, doğada farklı değerlere sahip örneklerin sistemli gözlemiyle sınanır.'),
  ('Bir tarım öğrencisi "Arı kovanlarına yakın tarlalarda ayçiçeği verimi daha yüksektir." hipotezini kuruyor. Hangi mekanizma bu hipotezin "çünkü" kısmını en iyi tamamlar?', 'Arılar tozlaşmayı artırarak tohum bağlamasını artırır', ['Arılar ayçiçeklerini sulamaktadır', 'Arılar tarladaki toprağı gevşetir', 'Arılar yabani otları yiyerek ayçiçeklerine yer açar ve gölgelemeyi azaltır'], 'Arıların ayçiçeğinde tozlaşmayı artırması bilinen bir mekanizmadır; hipotez bu mekanizmayla gerekçelendirilir ve ayrıca sınanabilir.'),
  ('Türkçe bilimsel metinlerde "hipotez" sözcüğünün karşılığı olarak da kullanılan terim hangisidir?', 'Denence', ['Sayıltı', 'Gözlence', 'Kanıtlama'], '"Denence", sınanmak üzere ileri sürülen geçici açıklama anlamında "hipotez"in Türkçe karşılığıdır. "Sayıltı" ise sınanmadan kabul edilen önermedir.'),
  ('Hipotezin "geçici" bir açıklama olarak nitelenmesinin nedeni nedir?', 'Sınanana kadar doğruluğu belli değildir ve kanıta göre değişebilir', ['Kısa sürede unutulduğu için', 'Yalnızca bir gün geçerli olduğu için', 'Araştırma bitince her zaman yanlış çıktığı ve bir daha kullanılmadığı için'], 'Hipotez, sınamanın sonucuna göre desteklenir, düzeltilir ya da bırakılır; kesinleşmiş bir bilgi değildir.'),
  ('Bir öğrenci kardeşinin her sınavdan önce midesinin ağrıdığını fark ederek "Sınav kaygısı fiziksel belirtilerle ilişkili mi?" sorusunu soruyor. Bu soru en çok hangi kaynaktan doğmuştur?', 'Kişisel gözlem ve deneyim', ['Kuramdan tümdengelim', 'Alanyazındaki çelişki', 'Önceki bir araştırmanın önerisi ve yöntem eleştirisi'], 'Gündelik yaşamda yapılan bir gözlem, araştırma sorusunun en yaygın kaynaklarından biridir; ancak soru yazılmadan önce alanyazın taranmalıdır.'),
  ('Bir araştırma sorusu için birden fazla hipotez kurulabilir mi?', 'Evet; sorunun farklı yönlerine ilişkin birden çok hipotez kurulabilir', ['Hayır; her soru için yalnızca bir hipotez kurulabilir', 'Hayır; hipotez sayısı soru sayısından az olmalıdır', 'Evet; ama bu hipotezlerin tümünün aynı sonucu öngörmesi ve birlikte desteklenmesi zorunludur'], 'Örneğin bir okuma programının hızı ve anlamayı ayrı ayrı nasıl etkileyeceğine ilişkin iki hipotez aynı soruya bağlı olabilir.'),
  ('İki ayrı hipotez aynı veriyle sınanacak: H1 "A yöntemi hızı artırır", H2 "A yöntemi doğruluğu artırır". Hız artıp doğruluk değişmezse sonuç nasıl raporlanır?', 'H1 desteklenmiş, H2 desteklenmemiştir', ['İki hipotez de desteklenmiştir', 'İki hipotez de çürütülmüştür', 'Hipotezler birbirine bağlı olduğu için hiçbir sonuç raporlanamaz ve deney yinelenmelidir'], 'Hipotezler ayrı yazıldığı için her biri kendi verisine göre ayrı ayrı değerlendirilir.'),
  ('Bir edebiyat öğrencisi "Tanzimat romanlarında kadın karakterler nasıl betimlenmiştir?" sorusunu soruyor. Bu soru için en uygun veri kaynağı hangisidir?', 'Dönemin romanlarının metinleri', ['Bugünkü okurlara yapılan anket', 'Romanların satış rakamları', 'Romanları basan matbaaların kuruluş yılları ve sahiplerinin adları'], 'Soru metinlerdeki betimlemeyi sorar; veri doğrudan romanların metinlerinin incelenmesinden gelir.'),
  ('Bir coğrafya öğrencisi "Kent merkezinde gece sıcaklıkları kırsal çevreden daha yüksektir." hipotezini kuruyor. Bu hipotezi sınamak için ölçümler nasıl planlanmalıdır?', 'Kent merkezi ve kırsalda aynı gece, aynı saatte, aynı tür termometreyle ölçüm', ['Kent merkezinde gündüz, kırsalda gece ölçüm', 'Yalnızca kent merkezinde ölçüm', 'Kırsalda yaşayanlara geceleri üşüyüp üşümediklerini sormak ve yanıtları karşılaştırmak'], 'Karşılaştırmanın adil olması için zaman ve ölçüm aracı aynı, yalnızca yer farklı olmalıdır.'),
  ('Bir demograf "Kadınların eğitim süresi arttıkça ilk doğum yaşı yükselir." hipotezini kuruyor. Bu hipotez hangi türdendir?', 'Yönlü ilişkisel hipotez', ['Yönsüz karşılaştırmalı hipotez', 'Sıfır hipotezi', 'Betimsel hipotez'], 'Hipotez iki sürekli değişkenin aynı yönde değiştiğini öne sürer; hem ilişkiseldir hem de yön belirtir.'),
  ('Bir öğrenci evde ekmek mayalanırken hamurun sıcak mutfakta daha hızlı kabardığını fark ediyor. Bu gözlemden kurulabilecek en uygun araştırma sorusu hangisidir?', 'Ortam sıcaklığı hamurun kabarma süresini nasıl etkiler?', ['Ekmek neden lezzetlidir?', 'Hamur yapmak zor mudur?', 'Mutfakta en çok hangi yemek pişirilir ve bunlardan hangisi en sevilir?'], 'Gözlem sıcaklık ile kabarma hızı arasında bir ilişki düşündürür; soru bu iki değişkeni açıkça içerir.'),
  ('"Kar yağışı olan günlerde okula geç kalan öğrenci sayısı artar." hipotezi hangi tür hipotezdir?', 'Yönlü', ['Yönsüz', 'Sıfır', 'Betimsel'], '"Artar" ifadesi etkinin yönünü belirtir.'),
  ('Bir araştırma sorusu yazılırken neden önce konu hakkında okuma yapılmalıdır?', 'Sorunun daha önce yanıtlanıp yanıtlanmadığını ve neyin bilindiğini öğrenmek için', ['Soruyu daha uzun yazabilmek için', 'Kaynakça sayfasını doldurmak için', 'Okuma yapmanın araştırma sorusuyla bir ilgisi olmadığını göstermek ve süreyi kısaltmak için'], 'Ön okuma, var olan bilgiyi gösterir; böylece zaten yanıtlanmış bir soru yinelenmez ve soru alanyazına anlamlı bir katkı sağlayacak biçimde kurulur.'),
  ('"Kediler köpeklerden daha iyi evcil hayvandır." ifadesi neden bir hipotez sayılmaz?', '"Daha iyi" bir kişisel değerlendirmedir ve ölçütü belirtilmemiştir', ['İki hayvan türü içerdiği için', 'Çok kısa olduğu için', 'Evcil hayvanlar bilimsel olarak incelenemediği için hiçbir hipotez kurulamaz'], '"Daha iyi" ölçütü belirtilmedikçe kişisel bir yargıdır. Ölçüt verilirse (örneğin bakım maliyeti) sınanabilir bir karşılaştırmaya dönüşür.'),
  ('Bir öğrenci sınıfında anket yapmadan önce "Arkadaşlarımın çoğu sabah kahvaltı yapmıyordur." diye düşünüyor. Bu düşünce araştırma sürecinde hangi öğeye karşılık gelir?', 'Betimsel bir hipotez', ['Bir bulgu', 'Bir sonuç', 'Bir sınırlılık'], 'Henüz veri toplanmadan öne sürülen ve sınanacak bir beklentidir; bir grubun durumuna ilişkin olduğu için betimseldir.'),
  ('"Okul kantininde fiyatlar düşürülürse meyve satışları artar." hipotezi için çürütücü sonuç hangisidir?', 'Fiyat düşürüldükten sonra meyve satışlarının değişmemesi ya da azalması', ['Fiyat düşürüldükten sonra meyve satışlarının artması', 'Kantinde meyve satılması', 'Fiyatların düşürülmesinin öğrencilerce fark edilmesi ve bunun konuşulması'], 'Hipotez artış öngörür; satışların aynı kalması ya da azalması bu öngörüyle çelişir.'),
  ('Bir araştırmanın hipotezi desteklenmediğinde bu durumun raporlanması bilimsel bilgiye nasıl katkı sağlar?', 'Başkalarının aynı beklentiyi gereksiz yere yeniden sınamasını önler ve bilgiye eklenir', ['Hiçbir katkı sağlamaz', 'Araştırmacının itibarını düşürür, bu yüzden gizlenmelidir', 'Yalnızca araştırmacının kendisi için önemlidir, başkalarıyla paylaşılmamalıdır'], 'Olumsuz sonuçlar da bilgi üretir: belirli bir etkinin bu koşullarda görülmediğini gösterir.'),
  ('Bir öğrencinin araştırma sorusu "Okulumuzdaki öğrencilerin en çok kullandığı ulaşım aracı nedir?" biçimindedir. Bu soruya en uygun veri toplama yolu hangisidir?', 'Öğrencilere okula nasıl geldiklerini soran kısa bir anket', ['Bir deney tasarlamak', 'Bir öğrenciyle uzun görüşme yapmak', 'Ulaşım araçlarının fiyatlarını internetten araştırmak ve bir tablo hazırlamak'], 'Betimsel bir sıklık sorusu, çok sayıda öğrenciden kısa bir anketle toplanan verilerle yanıtlanır.'),
  ('Bir öğrenci "Sıcak havada çikolata daha çabuk erir." diye düşünüyor. Bu düşünce bilimsel süreçte neye karşılık gelir?', 'Hipotez', ['Sonuç', 'Gözlem kaydı', 'Kaynakça'], 'Henüz sınanmamış, sıcaklık ile erime süresi arasında bir ilişki öneren bir beklentidir; bu bir hipotezdir.'),
  ('Bir öğrenci "Neden bazı insanlar sabahları daha enerjiktir?" sorusunu araştırmak istiyor. Bu soruyu daraltmak için ilk adım hangisi olabilir?', 'Ölçülecek bir etken seçmek, örneğin yatma saatini', ['Soruyu daha da genişletmek', 'Soruyu şiir biçiminde yazmak', 'Hiç kaynak okumadan rastgele bir grup seçip sonuç yazmak'], 'Geniş bir "neden" sorusu, incelenecek tek bir etkene odaklanarak daraltılır: "Yatma saati sabah enerji düzeyiyle ilişkili mi?"'),
  ('Aşağıdakilerden hangisi bir araştırma sorusu değil, bir konu başlığıdır?', 'Ergenlerde uyku düzeni', ['Ergenlerin hafta içi ve hafta sonu uyku süreleri farklı mı?', 'Ergenlerin yatma saati okul başarısıyla ilişkili mi?', 'Ergenler hafta sonu kaç saat uyuyor?'], '"Ergenlerde uyku düzeni" bir alanı adlandırır; soru biçiminde değildir ve neyin araştırılacağını belirtmez.'),
  ('Bir öğrenci "Kalın kitaplar ince kitaplardan daha az okunur." hipotezini kütüphane kayıtlarıyla sınamak istiyor. Hangi veri çifti gereklidir?', 'Kitapların sayfa sayısı ve ödünç alınma sayısı', ['Kitapların kapak rengi ve yazar adı', 'Kütüphanecinin adı ve çalışma saatleri', 'Kitapların fiyatı ve basıldığı matbaanın adresi'], 'Hipotezdeki değişkenler kitabın kalınlığı (sayfa sayısı) ve okunma sıklığıdır (ödünç alınma sayısı).'),
  ('Bir öğrencinin hipotezi "Güneşli günlerde okul bahçesinde daha çok kelebek görülür." biçimindedir. Hangisi bu hipotezle tutarlı bir tahmindir?', 'Gelecek iki haftada güneşli günlerdeki kelebek sayımları bulutlu günlerden yüksek olacaktır.', ['Kelebekler yalnızca bahar aylarında görülür.', 'Kelebeklerin kanatları renklidir.', 'Bulutlu günlerde bahçede daha çok kelebek görülecek, güneşli günlerde ise hiç görülmeyecektir.'], 'Tahmin, hipotezi belirli bir sayım planına uygular ve hipotez doğruysa gözlenecek sonucu söyler.'),
  ('Bir öğrenci okul yolunda gördüğü sokak köpeklerinin hep belirli bir kasabın önünde toplandığını fark ediyor. Bu gözlemden kurulabilecek en sınanabilir hipotez hangisidir?', 'Köpekler yiyecek kokusu ya da artıkları bulunan yerlerde toplanır.', ['Köpekler kasabı sevdiği için orada toplanır.', 'Köpekler her yerde eşit sayıda bulunur.', 'Köpekler kasabın önünde gizemli bir nedenle toplanır ve bu hiçbir zaman açıklanamaz.'], 'Yiyecek kaynağı açıklaması, örneğin farklı yiyecek dükkânlarının ve öteki dükkânların önündeki köpek sayıları karşılaştırılarak sınanabilir.'),
  ('Hipotez kurarken "Eğer ..., o zaman ..." kalıbının ilk kısmına genellikle hangi değişken yazılır?', 'Bağımsız değişken', ['Bağımlı değişken', 'Kontrol değişkeni', 'Karıştırıcı değişken'], '"Eğer" kısmı araştırmacının değiştirdiği ya da etkisini incelediği koşulu (bağımsız değişkeni), "o zaman" kısmı beklenen sonucu (bağımlı değişkeni) içerir.'),
  ('Bir öğrenci "Tuzlu suda yumurta yüzer." gözlemini bir hipoteze çevirmek istiyor. Hangisi en uygun hipotezdir?', 'Suya eklenen tuz miktarı arttıkça yumurtanın yüzme olasılığı artar.', ['Yumurta tuzlu suyu sever.', 'Yumurtalar her zaman batar.', 'Tuz yumurtanın kabuğunu eritip içini hafifletir ve bu nedenle yüzer.'], 'Doğru seçenek değiştirilecek etkeni (tuz miktarı) ve gözlenecek sonucu (yüzme) ilişkilendirir; farklı tuz miktarlarıyla sınanabilir.'),
  ('Hangi soru bir hipotezle değil, yalnızca betimsel bir araştırma sorusuyla ilerlemeye daha uygundur?', 'Okulumuzdaki öğrenciler hangi müzik türlerini dinliyor?', ['Müzik dinleyerek çalışmak hatırlamayı etkiler mi?', 'Müzik eğitimi alanların ritim testindeki puanları daha yüksek mi?', 'Hızlı tempolu müzik yazma hızını artırır mı?'], 'Doğru seçenek bir durumu betimlemeyi ister; ötekiler bir etki ya da fark sorduğu için hipotezle desteklenebilir.'),
  ('Bir öğrenci deney sonunda "Hipotezim doğrulandı, artık bu kesin bir gerçektir." diyor. Bu ifadenin sorunu nedir?', 'Tek bir deney hipotezi destekler ama kesinleştirmez', ['Deney sonuçları hiçbir zaman hipotezi desteklemez', 'Hipotezler deneyle sınanmaz', 'Sorun yoktur; desteklenen her hipotez kesin bir gerçek olur ve sorgulanmaz'], 'Bilimsel bilgi yeni kanıtlarla değişebilir; tek bir deney hipotezi yalnızca destekler. Yineleme ve farklı koşullarda sınama güveni artırır.'),
  ('Bir hipotezin "sade" olması ne demektir?', 'Gereksiz ayrıntı ve varsayım içermeden beklentiyi açıkça söylemesi', ['Hiç değişken içermemesi', 'Tek sözcükten oluşması', 'Herkesin önceden bildiği ve sınamaya gerek duyulmayan bir şeyi söylemesi'], 'Sade bir hipotez, beklenen ilişkiyi en az varsayımla ve açık bir dille ifade eder; bu onu anlaşılır ve sınanabilir kılar.'),
  ('Bir belediye için hazırlanan "Hangi kavşak düzenlemesi kazaları en çok azaltır?" sorusu hangi tür araştırma sorusudur?', 'Uygulamalı araştırma sorusu', ['Temel araştırma sorusu', 'Felsefi soru', 'Değer yargısı sorusu ve görüş bildirimi'], 'Soru belirli bir pratik sorunu çözmeye yöneliktir; sonucu doğrudan bir karara dönüşecektir.'),
  ('Bir öğrenci "Bitkiye müzik dinletmek büyümeyi hızlandırır." hipotezini sınamak için iki saksıdan birini müzikli odaya, ötekini müziksiz odaya koyuyor; ancak müzikli oda daha güneşli. Bu düzenekte hipotez açısından sorun nedir?', 'Büyüme farkı müzikten değil ışık farkından kaynaklanabilir', ['Müzik büyümeyi hiçbir zaman etkilemez', 'İki saksı karşılaştırma için fazladır', 'Müziğin türü belirtilmediği için deney hiç yapılamaz ve sonuç yazılamaz'], 'Işık da büyümeyi etkilediğinden iki koşul tek bir yönden (müzik) farklı olmalıdır; aksi hâlde sonuç hipotezi sınamaz.'),
  ('Bir öğrenci hem araştırma sorusunu hem hipotezini aynı cümleyle yazmıştır: "Ekran süresi uyku süresini kısaltır mı?" Bu cümle hangisi olarak kullanılabilir?', 'Araştırma sorusu; hipotez için bildirme cümlesine çevrilmelidir', ['Yalnızca hipotez', 'Hem soru hem hipotez olarak aynen', 'İkisi olarak da kullanılamaz ve konu değiştirilmelidir'], 'Soru cümlesi bir araştırma sorusudur. Hipotez bu soruya önerilen yanıttır: "Ekran süresi arttıkça uyku süresi kısalır."'),
  ('Bir öğrenci annesinin "Tencerenin kapağını kapatırsan su daha çabuk kaynar." sözünü sınamak istiyor. Hangisi bu söze dayanan sınanabilir bir hipotezdir?', 'Aynı miktar su, kapak kapalıyken kapak açık olduğundan daha kısa sürede kaynar.', ['Kapaklı tencereler daha güzeldir.', 'Su her zaman aynı sürede kaynar.', 'Kapak kapatılınca suyun tadı ve rengi değişir, bu da kaynamayı geciktirir.'], 'Doğru seçenek iki koşulu (kapak açık/kapalı) ve ölçülecek sonucu (kaynama süresi) belirtir; aynı ocak ve su miktarıyla sınanabilir.'),
  ('Bir öğrenci kedisinin hangi oyuncakla daha uzun oynadığını merak ediyor. Bu merakı ölçülebilir bir araştırma sorusuna en iyi dönüştüren seçenek hangisidir?', 'Kedim tüylü top ile ipli çubuktan hangisiyle 10 dakikalık sürede daha uzun oynuyor?', ['Kedim oyuncaklarını seviyor mu?', 'Kediler neden oyun oynar?', 'Bütün kediler hangi oyuncakları sever ve bunları nereden alırlar?'], 'Doğru seçenek karşılaştırılacak iki oyuncağı, gözlem süresini ve ölçülecek sonucu (oynama süresi) belirtir.'),
  ('Bir öğrenci kahve telvesinin saksı bitkilerine iyi geldiğini duymuş. Bunu sınamak için en uygun hipotez hangisidir?', 'Toprağına kahve telvesi karıştırılan fesleğenler, karıştırılmayanlardan dört haftada daha çok yaprak çıkarır.', ['Kahve telvesi bitkiler için iyidir.', 'Kahve telvesi kokuludur.', 'Kahve telvesi bitkileri sevindirir ve onları daha mutlu, daha canlı gösterir.'], 'Doğru seçenek müdahaleyi, karşılaştırma grubunu, süreyi ve ölçülebilir sonucu belirtir.'),
  ('Bir araştırma sorusunun oluşmasında genel olarak izlenen sıra hangisidir?', 'Merak, ön okuma, daraltma, soru yazma', ['Soru yazma, merak, daraltma, ön okuma', 'Ön okuma, soru yazma, merak, daraltma', 'Daraltma, merak, soru yazma, ön okuma'], 'Önce bir merak ya da sorun fark edilir, konu hakkında okunur, okunanlara göre konu daraltılır ve sonunda yanıtlanabilir bir soru yazılır.'),
  ('Bir öğrenci araştırma sorusu yazarken aşağıdakilerden hangisinden kaçınmalıdır?', 'Yanıtı baştan varsayan ifadelerden', ['Ölçülebilir kavramlardan', 'Grubu belirtmekten', 'Zaman ve yer sınırını belirtmekten'], 'Yanıtı varsayan ifadeler soruyu yönlendirici yapar. Ölçülebilir kavramlar, grup ve kapsam ise iyi bir sorunun öğeleridir.'),
  ('Bir ilkokul öğrencisi "Tahminimce kalın bardaktaki çay daha geç soğur." diyor. Öğretmeni bu cümleyi bilimsel bir hipoteze nasıl yaklaştırabilir?', '"Kalın camlı bardaktaki çay, ince camlıdakine göre 10 dakikada daha az soğur." biçiminde yazdırarak', ['Cümleyi olduğu gibi bırakarak', '"Çay sıcaktır." biçiminde yazdırarak', '"Kalın bardak daha güzeldir ve çay ondan içilmelidir." biçiminde yazdırarak'], 'Karşılaştırmayı, süreyi ve ölçülebilir sonucu (sıcaklık düşüşü) eklemek tahmini sınanabilir bir hipoteze dönüştürür.'),
  ('Bir hipotezin "basit" bir dille yazılması onu bilimsel açıdan zayıflatır mı?', 'Hayır; açık ve basit dil, hipotezin anlaşılmasını ve sınanmasını kolaylaştırır', ['Evet; bilimsel hipotezler mutlaka teknik terimlerle yazılmalıdır', 'Evet; basit hipotezler sınanamaz', 'Hayır; ama basit hipotezler yalnızca ilkokulda kullanılabilir, bilim insanları kullanmaz'], 'Bir hipotezin değeri dilinin karmaşıklığından değil, açıklığından ve sınanabilirliğinden gelir.'),
  ('Bir araştırmacının hipotezi "Öğrencilerin teneffüste fiziksel olarak etkin olma süresi, okul bahçesinde oyun çizgileri (seksek, labirent) boyandıktan sonra artar." biçimindedir. Hangi ölçüm bu hipotezi en doğrudan sınar?', 'Boyamadan önce ve sonra teneffüste etkin geçirilen sürenin gözlemle ölçülmesi', ['Öğrencilerin boyanmış çizgileri beğenip beğenmediğinin sorulması', 'Boyanın kaç kutu harcandığının hesaplanması', 'Bahçenin boyamadan sonra fotoğraflarının çekilip okul dergisinde yayımlanması'], 'Hipotez etkin geçirilen sürenin değişeceğini öngörür; bu, önce ve sonra yapılan gözlemlerle doğrudan ölçülür.'),
  ('Bir öğrenci kendi sınıfında "Ders başında 2 dakikalık sessiz okuma, dersin ilk 10 dakikasındaki gürültüyü azaltır." hipotezini sınıyor. Hangi karşılaştırma en uygundur?', 'Sessiz okumalı ve sessiz okumasız günlerde ilk 10 dakikadaki ses düzeyi', ['Yalnızca sessiz okumalı günlerdeki ses düzeyi', 'Sınıfın başka bir sınıfla boy ortalaması', 'Öğrencilerin sessiz okumayı sevip sevmediklerine ilişkin anket ve öğretmenin görüşü'], 'Hipotez bir uygulamanın etkisini öne sürer; uygulamanın olduğu ve olmadığı benzer günlerin karşılaştırılması gerekir.'),
  ('Bir öğrenci "Limon suyu kesilmiş elmanın kararmasını geciktirir." hipotezini kuruyor. Hangi sonuç bu hipotezi çürütür?', 'Limon suyu sürülen ve sürülmeyen dilimlerin aynı sürede kararması', ['Limon suyu sürülen dilimin daha geç kararması', 'Limon suyu sürülmeyen dilimin kararması', 'Limon suyu sürülen dilimin tadının ekşimsi olması ve kokusunun değişmesi'], 'Hipotez kararmanın gecikeceğini öngörür; iki dilimin aynı sürede kararması bu öngörüyle çelişir.'),
  ('Bir öğrenci okul bahçesinde çimleri biçilen ve biçilmeyen iki alan olduğunu fark ediyor. Bu durumdan hangi araştırma sorusu türetilebilir?', 'Biçilmeyen alanda biçilen alana göre daha çok böcek türü bulunuyor mu?', ['Çim biçmek güzel midir?', 'Bahçıvan çimleri neden biçiyor?', 'Çimler biçilmeli mi, yoksa doğal bırakılmalı mı ve bu kararı kim vermelidir?'], 'Var olan iki farklı alan doğal bir karşılaştırma olanağı sunar; böcek türü sayısı sayılarak ölçülebilir. Ancak iki alan başka yönlerden de farklı olabilir.'),
  ('Bir öğrencinin hipotezi "Topun içindeki hava basıncı arttıkça top daha yükseğe zıplar." biçimindedir. Bu hipotezden türetilecek en uygun tahmin hangisidir?', 'Aynı yükseklikten bırakılan topun, pompayla basıncı artırıldıkça zıplama yüksekliği artacaktır.', ['Top her zaman aynı yüksekliğe zıplayacaktır.', 'Basıncı düşük top daha yükseğe zıplayacaktır.', 'Topun rengi değiştirildiğinde zıplama yüksekliği de değişecek ve kırmızı top en yükseğe çıkacaktır.'], 'Tahmin, hipotezi belirli bir düzeneğe uygular: bırakma yüksekliği aynı tutulur, yalnızca basınç değiştirilir ve zıplama yüksekliği ölçülür.'),
  ('Bir öğrenci "Bu yaz kentimizde sivrisinekler geçen yazdan daha çok" gözlemini yapıyor. Bu gözlemi açıklamak için kurulabilecek ve verilerle sınanabilecek bir hipotez hangisidir?', 'Bu bahar yağışların daha fazla olması, su birikintilerini ve sivrisinek üremesini artırmıştır.', ['Sivrisinekler bu yıl daha sinirlidir ve insanları daha çok aramaktadır.', 'Sivrisinekler insanları özlemiştir.', 'Sivrisinekler her yıl rastgele çoğalır, bunun hiçbir nedeni yoktur ve araştırılamaz.'], 'Doğru seçenek ölçülebilir bir etken (yağış) ve bir mekanizma (su birikintisi, üreme) önerir; yağış ve sivrisinek sayımı verileriyle sınanabilir.'),
  ('Bir hipotez yazmadan önce ilgili değişkenleri listelemek araştırmacıya ne kazandırır?', 'Hangi değişkenin neden, hangisinin sonuç olarak ele alınacağını netleştirir', ['Hipotezi kendiliğinden doğru çıkarır', 'Kaynak okumaya ve alanyazını taramaya hiç gerek bırakmaz', 'Örneklem seçimini gereksiz kılar ve araştırmayı kısaltır'], 'Değişkenler listelenince roller belirlenir ve gözden kaçabilecek karıştırıcı etkenler de daha kolay fark edilir.'),
  ('Bir matematik öğretmeni "Öğrenciler problem çözerken çizim yaptığında doğru çözüm oranı artar." hipotezini kuruyor. Bu hipotezi sınamak için hangi veri gereklidir?', 'Çizim yapılan ve yapılmayan çözümlerde doğru çözüm oranları', ['Öğrencilerin en sevdiği geometrik şekil', 'Problemlerin kaç satırdan oluştuğu', 'Öğrencilerin çizim yeteneğini resim dersindeki notlarına bakarak belirlemek ve listelemek'], 'Hipotez çizim yapmanın doğru çözüm oranını etkilediğini öne sürer; iki koşuldaki oranların karşılaştırılması gerekir.'),
  ('Bir öğrenci "Okulda geri dönüşüm kutusu sayısı artırılırsa çöpe atılan plastik şişe sayısı azalır." hipotezini kuruyor. Hangi sonuç hipotezle tutarlıdır?', 'Kutu sayısı artırıldıktan sonra çöp kutularındaki plastik şişe sayısının düşmesi', ['Kutu sayısı artırıldıktan sonra çöpteki şişe sayısının artması', 'Geri dönüşüm kutularının boş kalması', 'Okulun kantinde plastik şişe satışını tamamen durdurması ve şişelerin hiç kullanılmaması'], 'Hipotez çöpe atılan şişelerin azalacağını öngörür; ama kantinde satışın durması gibi başka değişiklikler aynı sonucu doğurabileceğinden bunlar da izlenmelidir.'),
];
